import './style.css';
import {courseActivities,courseActivityById,checkCourseActivity} from './course-activities.js';
import {lecturerScenario,lecturerScenarioPt,lecturerStages} from './lecturer-case.js';
import {provenance,lessonSource,lessonCourseExtras,moduleCourseContent,activityCards,courseActivityPage,courseMaterialsPage,verification} from './course-view.js';
import {modules,questions,cases,allLessons,questionById,correctAnswer,sources} from './data.js';
import {comparisons,topologyFacts,casePT} from './content.js';
import {loadState,persistState,grade,answerText,recordAnswer,topicStats,dueCards,rateCard,createExam} from './study.js';
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let browserStorage;try{browserStorage=window.localStorage}catch{browserStorage={getItem(){throw new Error('Storage unavailable')},setItem(){throw new Error('Storage unavailable')}}}const loaded=loadState(browserStorage);let state=loaded.state,storageWarning=loaded.warning;
let page='Dashboard',moduleFilter=0,lesson=null,question=null,feedback=null,flipped=false,search='',caseIndex=0,caseRevealed=false,format='all',browseAll=false,flashId=null,quick=null,courseActivityId=null;
const icons={'Dashboard':'▦','Learn':'▤','Flashcards':'▱','Practice':'✎','Exam Mode':'◷','Mistake Notebook':'▧','Glossary':'Aa'};
const pt=s=>state.mode==='bilingual'?s:'';
const bilingual=(en,portuguese)=>`<p>${esc(en)}</p>${state.mode==='bilingual'&&portuguese?`<p class="portuguese" lang="pt">${esc(portuguese)}</p>`:''}`;
const accuracy=()=>state.answers.length?Math.round(state.answers.filter(a=>a.correct).length/state.answers.length*100):0;
const progress=m=>Math.round(m.lessons.filter(l=>state.done.includes(l.id)).length/m.lessons.length*100);
const activeMistakes=()=>Object.values(state.mistakes).filter(m=>!m.archived).sort((a,b)=>(b.updated||0)-(a.updated||0));
function save(){storageWarning=persistState(browserStorage,state);const status=$('.saved');if(status)status.textContent=storageWarning?'Progress not saved':'Progress saved locally';if(storageWarning&&!$('.storage-warning')){const banner=document.createElement('div');banner.className='storage-warning';banner.role='alert';banner.textContent=storageWarning;$('main')?.prepend(banner)}}
function navigate(target,opts={}){page=target;moduleFilter=opts.module??0;lesson=opts.lesson??null;courseActivityId=opts.activity??null;question=opts.question?questionById.get(String(opts.question)):null;feedback=null;search='';format='all';flipped=false;flashId=null;if(target!=='Practice')quick=null;caseRevealed=false;const query=new URLSearchParams();if(moduleFilter)query.set('module',moduleFilter);if(lesson)query.set('lesson',lesson);if(courseActivityId)query.set('activity',courseActivityId);if(question)query.set('question',question.id);history.pushState(null,'',`#${encodeURIComponent(page)}${query.size?'?'+query:''}`);$('#app').classList.remove('mobile-open');render();window.scrollTo(0,0);$('h1')?.focus({preventScroll:true})}
function readRoute(){const [name,params='']=location.hash.slice(1).split('?');const opts=new URLSearchParams(params);page=decodeURIComponent(name||'Dashboard');if(![...Object.keys(icons),'Module','MediMind','Course Activity','Course Materials'].includes(page))page='Dashboard';moduleFilter=Number(opts.get('module'))||0;if(moduleFilter<0||moduleFilter>12)moduleFilter=0;lesson=opts.get('lesson');if(!allLessons.some(l=>l.id===lesson))lesson=null;question=questionById.get(opts.get('question'))||null;feedback=null;courseActivityId=opts.get('activity');if(page==='Course Activity'&&!courseActivityById.has(courseActivityId))page='Learn';caseIndex=Math.min(4,Math.max(0,Number(opts.get('stage'))||0));caseRevealed=false;if(page==='Module'&&!moduleFilter)page='Learn';render()}
window.addEventListener('popstate',readRoute);
function shell(content){return `<a class="skip-link" href="#main-content">Skip to content</a><aside class="sidebar" id="main-sidebar"><a class="brand" href="#" data-nav="Dashboard"><span class="brand-icon">▥</span><span>Study Hub<small>INTRO TO COMPUTING</small></span></a><div class="workspace-label">INTRO TO COMPUTING STUDY HUB</div><nav aria-label="Main navigation">${Object.keys(icons).map(n=>`<button class="nav-item ${page===n?'active':''}" data-nav="${n}" ${page===n?'aria-current="page"':''}><span>${icons[n]}</span>${n}${n==='Mistake Notebook'&&activeMistakes().length?`<b>${activeMistakes().length}</b>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="course-badge">✦ <span>A little progress, every day.<small>You've got this.</small></span></div><div class="profile"><span class="avatar">SH</span><span>My study space<small>Higher Diploma · Ireland</small></span><span class="profile-dot"></span></div></div></aside><div class="main-wrap"><header class="topbar"><button class="mobile-toggle" aria-label="Toggle navigation" aria-expanded="false" aria-controls="main-sidebar">☰</button><div class="breadcrumb">My workspace <span>/</span> <strong>${page}</strong></div><div class="top-actions"><span class="saved"><i></i> ${storageWarning?'Progress not saved':'Progress saved locally'}</span><button id="language" class="language">◎ &nbsp;${state.mode==='bilingual'?'Bilingual mode':'English only'} <span>⌄</span></button><span class="avatar small">SH</span></div></header><main id="main-content" tabindex="-1">${storageWarning?`<div class="storage-warning" role="alert">${esc(storageWarning)} <button id="export-progress">Export progress</button></div>`:''}${content}<div class="backup-actions"><button class="text-button" id="export-progress-footer">Export progress backup ↓</button></div><footer>UNDERSTAND <span>→</span> RECOGNISE IN ENGLISH <span>→</span> PRACTISE <span>→</span> REMEMBER <span class="footer-right">Made for your next step.</span></footer></main></div>`}
function heading(eyebrow,title,subtitle,action=''){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${subtitle}</p></div>${action}</div>`}function button(label,attrs='',cls='primary'){return `<button class="${cls}" ${attrs}>${label}</button>`}function moduleSelect(){return `<label class="filter">Module <select id="module-filter"><option value="0">All modules</option>${modules.map(m=>`<option value="${m.id}" ${moduleFilter===m.id?'selected':''}>${m.id}. ${m.title}</option>`).join('')}</select></label>`}
function dashboard(){let completed=state.done.length,total=allLessons.length,weak=modules.map(m=>({m,stats:topicStats(state,m.id)})).filter(x=>x.stats.needsReview).sort((a,b)=>a.stats.accuracy-b.stats.accuracy);let last=allLessons.find(l=>l.id===state.last)||modules[0].lessons[0],lm=modules.find(m=>m.lessons.some(l=>l.id===last.id));return heading('YOUR PERSONAL LEARNING SPACE','A little learning. A lot of possibility.','Build your confidence in computing, one concept at a time.',`<div class="date-chip">✦ &nbsp; Your journey starts here</div>`)+`<section class="hero"><div class="hero-copy"><span class="pill">YOUR NEXT STEP</span><h2>Understand it today.<br>Remember it tomorrow.</h2><p>${pt('Aprenda no seu ritmo. ')}Learn the concepts.<br>Build your English. Feel ready for your exam.</p><button class="cream" data-lesson="${last.id}">Continue studying <span>↗</span></button><div class="hero-meta">MODULE ${lm.id} <span>·</span> ${lm.title}</div></div><div class="hero-art" aria-hidden="true"><div class="orbit orbit-one"></div><div class="orbit orbit-two"></div><div class="floating-tag tag-one">&lt;/&gt; &nbsp; Keep exploring</div><div class="book book-back"></div><div class="book book-front"><div class="book-top">A WORLD OF<br><b>POSSIBILITIES.</b></div><div class="book-chip">✧</div><div class="book-line"></div><div class="book-line short"></div><span>INTRO TO COMPUTING</span></div><div class="spark s1">✧</div><div class="spark s2">✦</div><div class="floating-tag tag-two">✓ &nbsp; One step closer</div></div></section><section class="course-progress"><div><h3>Course activity progress</h3><p>${Object.values(state.courseWork).filter(x=>x.review==='understood').length}/${courseActivities.length} reviewed · ${state.lecturerCaseDone.length}/5 lecturer MediMind stages attempted</p></div><button class="secondary" data-nav="Learn">Open course activities →</button></section><section class="stats"><div class="stat"><span class="stat-icon green">◔</span><div><small>Overall progress</small><strong>${Math.round(completed/total*100)}<em>%</em></strong><span>${completed} of ${total} concepts explored</span></div></div><div class="stat"><span class="stat-icon tan">☑</span><div><small>Questions answered</small><strong>${state.answers.length}</strong><span>Every question is a step forward</span></div></div><div class="stat"><span class="stat-icon purple">◎</span><div><small>Practice accuracy</small><strong>${accuracy()}<em>%</em></strong><span>${state.answers.length?'Keep building your confidence':'Your fresh start looks good'}</span></div></div><div class="stat"><span class="stat-icon blue">✧</span><div><small>Topics mastered</small><strong>${modules.filter(m=>topicStats(state,m.id).mastered).length}<em> / 12</em></strong><span>5 distinct questions · ≥80% latest correct</span></div></div></section><div class="dashboard-grid"><section><div class="section-title"><h2>Your learning path <span class="count">12 modules</span></h2><button class="text-button" data-nav="Learn">View all modules ↗</button></div><div class="module-grid">${modules.map(moduleCard).join('')}</div><div class="course-note">ⓘ &nbsp; Based on your 20 lecturer files. Course Activities keep original prompts; Generated Practice is labelled separately.</div></section><aside class="right-column"><div class="review-card"><span class="mini-label">MAKE IT STICK</span><div class="review-heading"><h3>Daily review</h3><span>☀</span></div><p>A few minutes today.<br>A stronger memory tomorrow.</p><div class="review-row"><span>▱ &nbsp; Flashcards to review</span><b>${dueCards(state).length}</b></div><div class="review-row"><span>↻ &nbsp; Mistakes to revisit</span><b>${activeMistakes().length+courseReviewEntries().length}</b></div><button class="primary full" data-nav="Flashcards">Start daily review <span>→</span></button><small>No pressure. Just progress.</small></div><div class="quick-card"><span class="quick-icon">ϟ</span><div><h3>A quick brain boost?</h3><p>Try a mixed-topic practice quiz.</p><button class="text-button" id="quick-quiz">Take a quick quiz →</button></div></div><div class="section-title review-title"><h3>Topics needing review</h3><span>↗</span></div><div class="weak-list">${weak.length?weak.slice(0,3).map(x=>`<button data-module="${x.m.id}">${x.m.title}<small>${x.stats.accuracy}% latest accuracy · Review →</small></button>`).join(''):`<div class="empty-mini"><span>♧</span><p>Your next insight is waiting.<small>Practise to discover topics to review.</small></p></div>`}</div>${courseReviewEntries().map(([id])=>`<button class="text-button" data-course-activity="${id}">Course review: ${esc(courseActivityById.get(id).title)} →</button>`).join('')}<div class="recent"><h3>Recent mistakes</h3>${activeMistakes().slice(0,2).map(x=>`<button data-retry="${x.id}">${esc(questionById.get(String(x.id)).prompt)}<span>Review →</span></button>`).join('')||'<p>A clean slate. Mistakes will appear here to help you learn.</p>'}</div></aside></div>`}
function moduleCard(m){return `<button class="module-card" data-module="${m.id}"><div class="module-card-top"><span class="module-icon color-${m.id%4}">${m.icon}</span><span class="module-number">MODULE ${String(m.id).padStart(2,'0')}</span><span class="card-arrow">↗</span></div><h3>${m.title}</h3><p>${m.subtitle}</p><div class="progress-track"><span style="width:${progress(m)}%"></span></div><div class="module-card-bottom"><span>${m.lessons.length} concepts</span><span>${progress(m)}% complete</span></div></button>`}

function topology(term,showName=true){
 const layouts={Bus:[[35,35],[90,35],[145,35],[200,35]],Ring:[[120,20],[200,65],[165,120],[75,120],[40,65]],Star:[[120,70],[30,20],[210,20],[30,120],[210,120]],Mesh:[[120,20],[200,65],[165,120],[75,120],[40,65]],'Tree / Hybrid':[[120,15],[65,65],[175,65],[30,120],[95,120],[145,120],[210,120]]};
 const nodes=layouts[term]||layouts.Star;let lines='';
 const line=(a,b)=>`<line x1="${a[0]}" y1="${a[1]}" x2="${b[0]}" y2="${b[1]}" stroke="#6d8d7b" stroke-width="3"/>`;
 if(term==='Bus'){lines=line([15,85],[225,85])+nodes.map(p=>line([p[0],p[1]],[p[0],85])).join('')}
 else if(term==='Ring')lines=nodes.map((p,i)=>line(p,nodes[(i+1)%nodes.length])).join('');
 else if(term==='Mesh')lines=nodes.flatMap((p,i)=>nodes.slice(i+1).map(q=>line(p,q))).join('');
 else if(term==='Tree / Hybrid')lines=[[0,1],[0,2],[1,3],[1,4],[2,5],[2,6]].map(([a,b])=>line(nodes[a],nodes[b])).join('');
 else lines=nodes.slice(1).map(p=>line(nodes[0],p)).join('');
 return `<svg class="topology" viewBox="0 0 240 145" role="img" aria-label="${showName?esc(term)+' topology':'Network topology identification exercise'}">${lines}${nodes.map(([x,y])=>`<rect x="${x-9}" y="${y-7}" width="18" height="15" rx="3" fill="#315d4d"/><path d="M${x-5} ${y+11}h10" stroke="#315d4d" stroke-width="3"/>`).join('')}</svg>`;
}
function hardwareDiagram(){return `<svg class="hardware-diagram" viewBox="0 0 360 210" role="img" aria-label="Simplified motherboard with a highlighted central square socket and long memory slots on its right"><rect x="20" y="15" width="320" height="180" rx="12" fill="#dfe9d7" stroke="#66845a"/><path d="M55 65h60v65h70M55 150h60v20h110" fill="none" stroke="#8fa680" stroke-width="4"/><rect x="95" y="45" width="90" height="90" rx="5" fill="#40653b"/><rect x="85" y="35" width="110" height="110" fill="none" stroke="#9c6b34" stroke-width="3" stroke-dasharray="6 4"/><text x="140" y="103" text-anchor="middle" font-size="32" fill="white">?</text><rect x="225" y="35" width="18" height="110" fill="#849d69"/><rect x="255" y="35" width="18" height="110" fill="#849d69"/><rect x="95" y="162" width="180" height="12" rx="3" fill="#72935c"/></svg>`}
function comparison(moduleId){const c=comparisons[moduleId];if(!c)return '';return `<section class="comparison-panel"><h2>${c.title}</h2><div class="table-scroll" role="region" aria-label="${c.title}" tabindex="0"><table><thead><tr>${c.headers.map(x=>`<th scope="col">${esc(x)}</th>`).join('')}</tr></thead><tbody>${c.rows.map(row=>`<tr>${row.map((x,i)=>i===0?`<th scope="row">${esc(x)}</th>`:`<td>${esc(x)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>${state.mode==='bilingual'?`<p class="portuguese" lang="pt">${c.pt}</p>`:''}</section>`}
function sourcePanel(moduleId){if(moduleId<10)return '';return `<details class="sources"><summary>Official reference sources</summary><p>Use your lecturer’s materials first. Legal duties depend on facts, role, scope and phased commencement; check current official text.</p>${sources.filter(s=>moduleId===12?s.title.startsWith('ACM'):true).map(s=>`<a href="${s.url}" target="_blank" rel="noopener noreferrer">${s.title} ↗</a>`).join('')}</details>`}
function flowDiagram(){return `<figure class="flow-diagram"><figcaption>Example: an age-check algorithm</figcaption><div>BEGIN → INPUT age</div><div class="flow-decision">Decision: age ≥ 18?</div><div class="flow-branches"><span>Yes → OUTPUT "Adult"</span><span>No → OUTPUT "Under 18"</span></div><div>END</div></figure>`}
function lessonView(){const l=allLessons.find(l=>l.id===lesson),m=modules[l.module-1];const q=questions.find(q=>q.conceptIds?.includes(l.id))||questions.find(q=>q.module===l.module&&q.type==='identify');const result=state.checks[l.id];return `<button class="text-button" data-module="${m.id}">← ${m.title}</button>`+heading(`MODULE ${m.id} · CONCEPT LESSON`,l.term,'Understand the idea. Recognise the English. Remember the concept.')+`<div class="lesson-layout"><article class="lesson-content">${lessonSource(l,state.mode)}<section class="lesson-block"><span class="mini-label">01 / BIG IDEA</span><h2>${esc(state.mode==='bilingual'?l.bigIdeaPt:l.bigIdeaEn)}</h2></section><section class="definition"><span class="mini-label">02 / ENGLISH DEFINITION</span>${l.fullName?`<h3>${l.fullName}</h3>`:''}<p>${esc(l.en)}</p></section>${state.mode==='bilingual'?`<section class="lesson-block" lang="pt"><span class="mini-label">03 / EXPLICAÇÃO EM PORTUGUÊS</span><p>${esc(l.pt)}</p></section>`:''}<section class="lesson-block"><span class="mini-label">04 / KEY ENGLISH TERMS</span><p class="term-chip">${l.term}</p><p>${state.mode==='bilingual'?esc(l.meaning):esc(l.keywords||l.fullName||l.en)}</p>${l.keywords?`<p><b>Layer:</b> ${l.layer} · ${l.term}</p><p><b>Main function:</b> ${esc(l.en.split(': ').slice(1).join(': '))}</p><p><b>Keywords:</b> ${l.keywords}</p>`:''}</section><section class="lesson-block"><span class="mini-label">05 / EXAMPLE</span>${bilingual(l.exampleEn,l.examplePt)}${topologyFacts[l.term]?topology(l.term)+topologyDetail(l.term):''}${lessonCourseExtras(l,state.mode)}${['RAM','Storage','Symmetric Cryptography','Asymmetric Cryptography','TCP','UDP','providers','deployers','Decomposition','Abstraction'].includes(l.term)?comparison(l.module):''}</section><section class="remember"><span>✦</span><div><b>06 / REMEMBER THIS</b>${bilingual(l.rememberEn,l.rememberPt)}</div></section><section class="lesson-block"><span class="mini-label">07 / CHECK YOUR UNDERSTANDING</span>${provenance(q.sourceIds,'generated')}<p>${q.prompt}</p>${q.options.map((x,i)=>`<button class="answer-option concept-answer ${result?.correct&&i===q.answer?'correct':''}" data-concept="${l.id}" data-question="${q.id}" data-value="${i}" ${result?.correct?'disabled':''}>${esc(x)}</button>`).join('')}<div id="concept-feedback" role="status">${result?`<div class="feedback ${result.correct?'success':'failure'}"><b>${result.correct?'✓ Correct':'↻ Review and try again'}</b>${bilingual(q.why,q.ptWhy)}</div>`:''}</div></section><button class="primary" id="complete-lesson">${state.done.includes(l.id)?'✓ Completed · Continue':'Mark complete & continue'} →</button>${sourcePanel(l.module)}</article><aside class="lesson-toc"><h3>In this module</h3>${m.lessons.map(x=>`<button class="${x.id===l.id?'selected':''}" data-lesson="${x.id}" ${x.id===l.id?'aria-current="page"':''}>${state.done.includes(x.id)?'✓':'○'} ${x.term}</button>`).join('')}</aside></div>`}
function topologyDetail(term){const f=topologyFacts[term];return `<div class="topology-facts"><p><b>How it works:</b> ${f.how}</p><p><b>Advantage:</b> ${f.adv}</p><p><b>Disadvantage:</b> ${f.dis}</p><p><b>Practical example:</b> ${f.example}</p>${state.mode==='bilingual'?`<p class="portuguese" lang="pt">${f.pt}</p>`:''}</div>`}
function learn(){if(lesson)return lessonView();return heading('YOUR LEARNING PATH','Big ideas. Small, clear steps.','12 modules to help you understand computing and speak its language.')+`<div class="notice">${pt('Explicações em português. ')}English definitions and technical terms, always. Course explanations follow your lecturer files. Original Course Activities and Generated Practice are identified separately. <button class="text-button" data-nav="Course Materials">View all 20 sources →</button></div><div class="module-grid all-modules">${modules.map(moduleCard).join('')}</div>${activityCards(0,state.courseWork)}<div class="case-banner"><div><span class="mini-label">PUT IT ALL TOGETHER</span><h2>MediMind case study</h2><p>Explore privacy, AI bias and professional responsibility through five decisions.</p><p>${state.lecturerCaseDone.length}/5 lecturer stages attempted</p></div><button class="primary" data-nav="MediMind">Explore the case →</button></div>`}
function moduleDetail(){const m=modules[moduleFilter-1];const renderLessons=list=>list.map(l=>`<button data-lesson="${l.id}"><span class="module-icon">${state.done.includes(l.id)?'✓':m.icon}</span><span><h3>${l.layer?`${l.layer} · `:''}${l.term}</h3><p>${esc(l.en)}</p></span><span>→</span></button>`).join('');return `<button class="text-button" data-nav="Learn">← All modules</button>`+heading(`MODULE ${m.id}`,m.title,m.subtitle)+comparison(m.id)+moduleCourseContent(m.id,state.mode,state.courseWork)+(m.id===5?`<section class="comparison-panel"><h2>How a network works</h2><ol><li>Establishing the network: connect Nodes through NICs and links.</li><li>Communication protocols: use agreed rules.</li><li>Data transmission: send formatted data through links.</li><li>Routing: forward Packets between networks.</li><li>Data receipt / confirmation: receive data; TCP provides acknowledgements and resending, UDP does not by itself.</li></ol>${bilingual('Like a postal service: connect, agree the format, send, route and receive.','Como os correios: conectar, combinar formato, enviar, encaminhar e receber. TCP confirma; UDP não confirma por si só.')}</section>`:'')+`${m.id===12?`<section class="acm-sections">${[[0,8],[8,16],[16,17],[17,18]].map(([start,end])=>`<h2>${m.lessons[start].term}</h2><div class="lesson-list">${renderLessons(m.lessons.slice(start,end))}</div>`).join('')}</section>`:`<div class="lesson-list">${renderLessons(m.lessons.filter(l=>!l.advanced))}</div>`}${m.lessons.some(l=>l.advanced)?`<details class="advanced" open><summary>Advanced / Course Material</summary><div class="lesson-list">${renderLessons(m.lessons.filter(l=>l.advanced))}</div></details>`:''}<div class="activity-actions"><button class="primary" id="module-practice">Practise this module →</button><button class="secondary" id="module-flashcards">Review flashcards</button></div>${sourcePanel(m.id)}`}
function flashcards(){const due=dueCards(state,moduleFilter);const pool=browseAll?allLessons.filter(l=>!moduleFilter||l.module===moduleFilter):due;if(!pool.some(l=>l.id===flashId))flashId=pool[0]?.id;const c=pool.find(l=>l.id===flashId);return heading('ACTIVE RECALL','A small card. A stronger memory.','Recall the English definition first. Ratings schedule the next review.')+moduleSelect()+`<div class="flash-toolbar"><p class="muted">${due.length} due · Again 1 min · Hard 10 min · Good 1 day · Easy 4 days</p><button class="text-button" id="toggle-browse">${browseAll?'Show due cards only':'Browse all cards'}</button></div>${!c?`<div class="empty-state"><span>✓</span><h2>You’re up to date.</h2><p>No cards are due in this selection. Return later or browse all cards.</p></div>`:`<div class="flashcard-wrap">${provenance(c.sourceIds,c.provenance)}<div class="card-counter">MODULE ${c.module} · ${modules[c.module-1].title}<span>${pool.length} ${browseAll?'available':'due'}</span></div><button class="flashcard ${flipped?'flipped':''}" id="flip-card" aria-label="${flipped?'Definition for':'Reveal definition for'} ${esc(c.term)}"><span class="mini-label">${flipped?'THE DEFINITION':'WHAT DOES THIS MEAN?'}</span><h2>${c.term}</h2>${flipped?bilingual(c.en,c.pt):'<div class="card-decoration" aria-hidden="true">✧</div>'}<small>${flipped?'How well did you remember?':'Click to reveal · Think in English first'}</small></button>${flipped?`<div class="rating-buttons">${['Again','Hard','Good','Easy'].map((x,i)=>`<button data-rate="${i}" data-card="${c.id}">${x}<small>${['1 min','10 min','1 day','4 days'][i]}</small></button>`).join('')}</div>`:'<p class="center muted">Missed and due cards come first.</p>'}</div>`}`}

const typeNames={choice:'Multiple choice',matching:'Identify the match',pairs:'Matching',fill:'Fill in the blank',ordering:'Ordering',build:'Build an algorithm',boolean:'True / False',identify:'Identify the concept',scenario:'Scenario',diagram:'Diagram recognition',classify:'Classification'};
function questionPool(){return questions.filter(q=>(!moduleFilter||q.module===moduleFilter)&&(format==='all'||q.type===format))}
function pickQuestion(exclude){const pool=questionPool().filter(q=>q.id!==exclude);return (pool.length?pool:questionPool())[Math.floor(Math.random()*(pool.length||questionPool().length))]}
function questionDraft(q,inExam=false){const drafts=inExam?state.exam.drafts||(state.exam.drafts={}):state.drafts;if(drafts[q.id]===undefined)drafts[q.id]=q.type==='build'?[]:q.type==='ordering'?[...q.options.slice(1),q.options[0]]:q.type==='pairs'||q.type==='classify'?q.options.map(()=> ''):'';return drafts[q.id]}
function setDraft(q,value,inExam=false){if(inExam){state.exam.drafts||={};state.exam.drafts[q.id]=value}else state.drafts[q.id]=value;save()}
function controls(q,inExam){const value=questionDraft(q,inExam);const disabled=feedback&&!inExam;const common=`${disabled?'disabled':''}`;
 if(q.type==='build')return `<div class="algorithm-builder"><h3>Available instructions</h3><div class="step-bank">${[...q.options].reverse().map(x=>`<button class="secondary" data-add-step="${q.options.indexOf(x)}" ${value.includes(x)||disabled?'disabled':''}>+ ${esc(x)}</button>`).join('')}</div><h3>Your algorithm</h3><ol>${value.map((x,i)=>`<li>${esc(x)} <button class="text-button" data-remove-step="${i}" ${disabled?'disabled':''} aria-label="Remove ${esc(x)}">Remove ×</button></li>`).join('')}</ol><p class="muted">${value.length}/${q.options.length} instructions placed</p></div>`;
 if(q.type==='fill')return `<label class="blank-label">Your English answer<input id="blank-answer" data-response="fill" value="${esc(value)}" autocomplete="off" placeholder="Type the missing term…" ${common}></label>`;
 if(q.type==='ordering')return `<p class="muted">Use the arrows to arrange every step, then submit.</p><div class="order-list">${value.map((x,i)=>`<div><span>${i+1}</span><b>${esc(x)}</b><button data-move="${i}" data-direction="-1" aria-label="Move ${esc(x)} up" ${common} ${i===0?'disabled':''}>↑</button><button data-move="${i}" data-direction="1" aria-label="Move ${esc(x)} down" ${common} ${i===value.length-1?'disabled':''}>↓</button></div>`).join('')}</div>`;
 if(q.type==='pairs'||q.type==='classify'){const choices=q.type==='pairs'?q.options.map(x=>x.split('|')[1]):q.categories;const rotated=q.type==='pairs'?[...choices.slice(1),choices[0]]:choices;return `<div class="pair-list">${q.options.map((x,i)=>`<label><b>${esc(q.type==='pairs'?x.split('|')[0]:x)}${q.pairDiagrams?topology(q.pairDiagrams[i],false):''}</b><select class="pair-answer" data-response="array" data-index="${i}" ${common}><option value="">Choose…</option>${rotated.map(v=>`<option value="${esc(v)}" ${value[i]===v?'selected':''}>${esc(v)}</option>`).join('')}</select></label>`).join('')}</div>`}
 return `<fieldset class="options" ${common}><legend class="sr-only">Choose one answer</legend>${q.options.map((o,i)=>`<label class="answer-option ${disabled&&i===q.answer?'correct':''} ${disabled&&String(value)===String(i)&&i!==q.answer?'incorrect':''}"><input type="radio" name="answer" data-response="choice" value="${i}" ${String(value)===String(i)?'checked':''}><span class="option-letter">${String.fromCharCode(65+i)}</span><span>${esc(o)}</span></label>`).join('')}</fieldset>`;
}
function feedbackHTML(q,result){const wrongDefinition=!result.correct&&!['ordering','pairs','classify','fill'].includes(q.type)?allLessons.find(l=>l.en===q.options[Number(result.value)]):null;return `<div class="feedback ${result.correct?'success':'failure'}" role="status" tabindex="-1"><h3>${result.correct?'✓ Well done. You’ve got it.':'↻ A useful learning moment.'}</h3><p><strong>Correct answer:</strong> ${esc(correctAnswer(q))}</p>${bilingual(q.why,q.ptWhy)}${wrongDefinition?`<p>Your chosen definition describes <b>${wrongDefinition.term}</b>.</p>`:''}${q.keywords?.length?`<div class="keyword">KEY ENGLISH TERMS · ${q.keywords.map(x=>`<b>${esc(x)}</b>`).join(' · ')}</div>`:''}</div>`}
function questionHTML(q,inExam=false){return `<div class="question-meta" data-question-id="${esc(q.id)}"><span class="pill light">MODULE ${q.module}</span><span>${typeNames[q.type]}</span></div>${provenance(q.sourceIds,'generated')}<h2 class="question-prompt">${esc(q.prompt)}</h2>${q.type==='diagram'?(q.diagramKind==='hardware'?hardwareDiagram():topology(q.diagram||'Star',false)):''}${q.code?`<pre class="pseudocode">${esc(q.code)}</pre>`:''}${controls(q,inExam)}<div id="answer-error" role="alert"></div>${!feedback||inExam?button(inExam?(state.exam.index===state.exam.ids.length-1?'Submit exam':'Save answer & continue →'):'Check answer →','id="submit-answer"'):feedbackHTML(q,feedback)+button(quick?'Continue quiz →':'Next question →','id="next-question"')}`}
function practice(){if(quick?.finished){const score=quick.results.filter(x=>x.correct).length;return heading('QUICK QUIZ COMPLETE',`${score} / ${quick.ids.length} correct`,'Review your mistakes or continue with another topic.')+`<div class="exam-score"><strong>${Math.round(score/quick.ids.length*100)}<small>%</small></strong><div><button class="primary" data-nav="Mistake Notebook">Study my mistakes →</button><button class="secondary" id="quick-quiz">Try another quick quiz</button></div></div>`}if(!question)question=quick?questionById.get(String(quick.ids[quick.index])):pickQuestion();const pool=questionPool();return heading(quick?'QUICK QUIZ · '+(quick.index+1)+' / '+quick.ids.length:'LEARN BY DOING','Make your knowledge stick.','Generated quizzes are scored; original open course tasks are self-assessed.')+(!quick?`<details class="practice-course-link"><summary>Lecturer Material / Course Activities</summary>${activityCards(moduleFilter,state.courseWork)}</details>`:'')+(!quick?`<div class="practice-filters">${moduleSelect()}<label class="filter">Format<select id="format-filter"><option value="all">All formats</option>${Object.entries(typeNames).map(([value,label])=>`<option value="${value}" ${format===value?'selected':''}>${label}</option>`).join('')}</select></label><label class="filter activity-picker">Choose an activity<select id="activity-select">${pool.map(q=>`<option value="${q.id}" ${question.id===q.id?'selected':''}>${esc(q.prompt)}</option>`).join('')}</select></label></div>`:'')+(question?`<div class="practice-layout"><article class="question-card">${questionHTML(question)}</article><aside class="practice-tip"><span>✦</span><h3>Look for the keywords.</h3>${bilingual('English keywords are clues to the right answer.','Observe os English keywords que indicam o conceito.')}<hr><p>Your practice accuracy</p><strong>${accuracy()}%</strong><small>${state.answers.length} questions answered</small><button class="text-button" data-nav="Mistake Notebook">Visit your mistake notebook →</button></aside></div>`:`<div class="empty-state"><h2>No activities in this selection.</h2><p>Choose a different module or format.</p></div>`)}
function examPage(){const exam=state.exam;if(!exam)return heading('EXAM MODE','Find your exam-day confidence.','Mixed topics. All question formats. Feedback after submission.')+`<div class="exam-intro"><span class="exam-symbol">◷</span><h2>Your next practice exam</h2><p>12 questions · one from each module<br>Answers stay hidden until you submit.</p><div class="notice">Untimed. In-progress answers and the final result are saved locally.</div><button class="primary" id="start-exam">Start mock exam →</button></div>${state.examHistory.length?`<section class="comparison-panel"><h2>Previous attempts</h2>${state.examHistory.slice().reverse().map(x=>`<p>${new Date(x.date).toLocaleDateString()} · ${x.correct}/${x.total} (${Math.round(x.correct/x.total*100)}%)</p>`).join('')}</section>`:''}`;
 if(!exam.finished){const q=questionById.get(String(exam.ids[exam.index]));return heading('MOCK EXAM',`Question ${exam.index+1} of ${exam.ids.length}`,'Take your time. Answers are revealed only after final submission.')+`<div class="progress-track exam-progress" role="progressbar" aria-valuemin="0" aria-valuemax="12" aria-valuenow="${exam.index}"><span style="width:${exam.index/exam.ids.length*100}%"></span></div><article class="question-card exam-question">${questionHTML(q,true)}${exam.index?'<button class="text-button" id="exam-back">← Previous question</button>':''}</article>`}
 const correct=exam.results.filter(r=>r.correct).length;const scores=modules.map(m=>{const rs=exam.results.filter((r,i)=>questionById.get(String(exam.ids[i])).module===m.id);return {m,total:rs.length,correct:rs.filter(r=>r.correct).length}});return heading('EXAM COMPLETE','Every attempt moves you forward.',`${correct} correct · ${exam.ids.length-correct} incorrect · ${Math.round(correct/exam.ids.length*100)}%`)+`<div class="exam-score"><strong>${Math.round(correct/exam.ids.length*100)}<small>%</small></strong><div><h2>${correct} / ${exam.ids.length} questions correct</h2><p>Use the review below to choose your next step.</p><button class="primary" data-nav="Mistake Notebook">Study my mistakes →</button> <button class="secondary" id="new-exam">New exam</button></div></div><h2>Performance by topic</h2><div class="topic-results">${scores.map(x=>`<div><span>${x.m.title}</span><b class="${x.correct===x.total?'green-text':'orange-text'}">${x.correct}/${x.total} · ${Math.round(x.correct/x.total*100)}%</b></div>`).join('')}</div><section class="comparison-panel"><h2>Weakest topics</h2>${scores.filter(x=>x.correct<x.total).map(x=>`<button class="text-button" data-module="${x.m.id}">${x.m.title} · Review →</button>`).join('')||'<p>No missed topics in this attempt. Keep practising distinct questions.</p>'}</section><h2>Full answer review</h2>${exam.results.map((r,i)=>{const q=questionById.get(String(exam.ids[i]));return `<details class="review-detail"><summary>${r.correct?'✓':'↻'} ${esc(q.prompt)}</summary><p>Your answer: ${esc(answerText(q,r.value))}</p>${feedbackHTML(q,r)}</details>`}).join('')}`}
function mistakes(){const list=Object.values(state.mistakes);const active=list.filter(x=>!x.archived),archived=list.filter(x=>x.archived);const group=items=>modules.filter(m=>items.some(x=>questionById.get(String(x.id)).module===m.id)).map(m=>`<section class="mistake-group"><h2>${m.title}</h2>${items.filter(x=>questionById.get(String(x.id)).module===m.id).map(x=>{const q=questionById.get(String(x.id));return `<article class="mistake-card"><h3>${esc(q.prompt)}</h3><p class="muted">Your last incorrect answer: ${esc(x.answer||'Not recorded in this older attempt')}</p><details><summary>Reveal explanation</summary><p><b>Correct answer:</b> ${esc(correctAnswer(q))}</p>${bilingual(q.why,q.ptWhy)}</details><div><button class="primary" data-retry="${q.id}">Retry question →</button><button class="text-button" data-understood="${q.id}">${x.archived?'Restore to review ↶':'Mark as understood ✓'}</button></div><small>${x.streak}/2 consecutive correct retries · ${x.archived?'Archived':'In review'}</small></article>`}).join('')}</section>`).join('');return heading('YOUR MISTAKE NOTEBOOK','Mistakes are part of the method.','Review the reason. Retry. Two consecutive correct answers archive a mistake.')+(active.length?group(active):`<div class="empty-state"><span>♧</span><h2>A fresh page.</h2><p>Incorrect answers are saved here automatically.</p><button class="primary" data-nav="Practice">Start practising →</button></div>`)+courseNotebook()+ (archived.length?`<details class="archive"><summary>Understood / archived (${archived.length})</summary>${group(archived)}</details>`:'')}
function glossary(){const list=allLessons.filter(l=>(!moduleFilter||l.module===moduleFilter)&&`${l.term} ${l.fullName||''} ${l.en} ${l.pt} ${l.meaning}`.toLowerCase().includes(search.toLowerCase()));return heading('YOUR COMPUTING COMPANION','The words behind the ideas.','English terminology, with Portuguese support when you need it.')+`<div class="glossary-toolbar"><label class="search-input"><span aria-hidden="true">⌕</span><span class="sr-only">Search glossary</span><input id="glossary-search" type="search" placeholder="Search a term or definition…" value="${esc(search)}"></label>${moduleSelect()}</div><p class="muted">${list.length} terms</p><div class="glossary-grid">${list.map(l=>`<article class="glossary-card"><span class="mini-label">MODULE ${l.module}</span><h3>${l.term}</h3>${l.fullName?`<h4>${l.fullName}</h4>`:''}<p><b>EN</b> ${esc(l.en)}</p>${state.mode==='bilingual'?`<p class="portuguese" lang="pt"><b>PT</b> ${esc(l.pt)}</p>`:''}<button class="text-button" data-lesson="${l.id}">Explore concept ↗</button></article>`).join('')||'<p>No matching terms. Try another keyword.</p>'}</div>`}
const caseEn=[
 ['GDPR: the combination of age, postcode, symptoms and timestamps may permit re-identification. Removing names does not establish anonymisation. Personal health data requires a lawful basis and an applicable special-category condition.','Respect privacy and avoid harm from unexpected or unsafe secondary uses.','ACM 1.6 Respect privacy and 2.5 Evaluate systems and risks: assess re-identification and document decisions.','Pause the sale pending competent assessment, minimise data and establish lawful purposes. Pseudonymisation is not anonymisation.'],
 ['Assess GDPR and AI Act obligations based on intended use, classification and role. Health AI is not automatically high-risk.','Bias and unfair outcomes can harm older users.','ACM 1.4 and 1.2: evaluate subgroup outcomes and communicate limitations.','Investigate causes, improve representative data, test by age group, use human oversight and restrict unsafe use.'],
 ['Assess GDPR breach notification: notify the authority within 72 hours of awareness unless unlikely to risk rights and freedoms. Inform affected people if high risk, subject to applicable exceptions.','Protect privacy and confidentiality; communicate honestly about impact.','ACM 1.7 and 2.9: protect entrusted data and maintain robust, usable security.','Contain, preserve evidence, assess impact, document, notify where required and remediate.'],
 ['Assess DSA duties according to service type and size, plus other applicable laws. Harmful content is not automatically illegal.','Avoid harm and protect minors and vulnerable users.','ACM 1.1 Public good and 1.2 Avoid harm: create safer conditions.','Improve moderation, reporting and age-appropriate safeguards; escalate serious health risks to qualified support.'],
 ['Assess applicable protected-disclosure law and reporting channels; legal protection depends on the facts.','Public interest, honesty and harm prevention can require concerns to be raised.','ACM 1.2, 1.3 and leadership principles: listen, investigate and address risks.','Document concerns, investigate independently, protect against retaliation and use appropriate escalation while safeguarding confidential data.']
];
function casePage(){
 const c=lecturerStages[caseIndex],notes=state.caseNotes[caseIndex]||['','','',''],roleNotes=state.caseRoleNotes[caseIndex]||['',''];
 const prompts=['What legal issue is involved?','What ethical issue is involved?','What professional responsibility is involved?','What should the organisation do?'];
 return `<button class="text-button" data-nav="Learn">← Back to Learn</button>`+heading('LECTURER MATERIAL / COURSE ACTIVITY','MediMind',`Stage ${caseIndex+1} of 5 · MindCheck board review`)+provenance(['T06','T05'])+`<section class="comparison-panel original-scenario"><h2>Original lecturer scenario</h2>${bilingual(lecturerScenario,lecturerScenarioPt)}<p>The CEO asks the board: launch, delay, or change course?</p><details><summary>Original workshop format · T06</summary><p>Brief: 5 min. Group work: 20 min. Board meeting: 15 min, with each group presenting for 3 minutes. Debrief: 10 min. The Study Hub supports individual study; this is not a live group timer.</p></details><details><summary>Read all five events (student scenario)</summary>${lecturerStages.map(x=>`<h3>${x.title}</h3><p>${esc(x.event)}</p>`).join('')}</details></section><div class="case-stages" aria-label="Case study stages">${lecturerStages.map((x,i)=>`<button data-case="${i}" ${i===caseIndex?'aria-current="step"':''}>${state.lecturerCaseDone.includes(i)?'✓ ':''}${i+1}. ${x.title}</button>`).join('')}</div><article class="case-study"><span class="pill light">${c.title}</span><h2>${esc(c.event)}</h2>${state.mode==='bilingual'?`<p lang="pt" class="portuguese">${esc(c.pt)}</p>`:''}<section class="role-questions"><h2>Group ${caseIndex+1} · ${c.role}</h2><p>Original role questions · T06. Give the law, an ethical issue beyond it, and a recommendation.</p>${c.questions.map((x,i)=>`<label>${esc(x)}${state.mode==='bilingual'?`<span lang="pt" class="field-translation">${esc(c.questionsPt[i])}</span>`:''}<textarea data-role-note="${i}" rows="3">${esc(roleNotes[i])}</textarea></label>`).join('')}</section><h3>Study Hub reflection scaffold</h3><p>These four reflection prompts support the original task. Written work is self-assessed, not automatically graded.</p>${prompts.map((x,i)=>`<label>${i+1}. ${x}<textarea data-note="${i}" placeholder="${pt('Escreva suas ideias… / ')}Write your reasoning…" rows="3">${esc(notes[i])}</textarea></label>`).join('')}${caseRevealed?`<section class="tutor-guidance" data-answer-material="true"><h2>Tutor guidance · T05 Complete</h2><blockquote>${esc(c.tutor)}</blockquote>${state.mode==='bilingual'?`<p lang="pt" class="portuguese">${esc(c.tutorPt)}</p>`:''}<h3>Study clarification · verify current/applicable law</h3>${bilingual(c.note,c.notePt)}</section><div class="feedback success"><h3>Study explanation · four responsibilities</h3>${prompts.map((p,i)=>`<section class="case-explanation"><h4>${p}</h4>${bilingual(caseEn[caseIndex][i],casePT[caseIndex][i])}</section>`).join('')}<small>These explanations supplement the tutor guidance; they are not additional lecturer answer keys.</small></div><button class="primary" id="next-case">${caseIndex===4?'Finish case study':'Next stage →'}</button>${caseIndex===4?'<button class="secondary" data-course-activity="medimind-board">Board decision & original debrief →</button>':''}`:`<button class="primary" id="reveal-case">Reveal explanation →</button>`}<div id="case-error" role="alert"></div>${sourcePanel(10)}</article>`;
}
function courseReviewEntries(){return Object.entries(state.courseWork).filter(([id,x])=>courseActivityById.has(id)&&x.review==='needs-review')}
function courseNotebook(){const entries=courseReviewEntries();return entries.length?`<section class="course-notebook"><h2>Course activities needing review</h2><p class="muted">Self-assessed course work is tracked separately from scored quiz accuracy.</p>${entries.map(([id])=>`<button class="answer-option" data-course-activity="${id}">${esc(courseActivityById.get(id).title)} · Retry →</button>`).join('')}</section>`:''}
function render(){let content=page==='Dashboard'?dashboard():page==='Learn'?learn():page==='Module'?moduleDetail():page==='Flashcards'?flashcards():page==='Practice'?practice():page==='Exam Mode'?examPage():page==='Mistake Notebook'?mistakes():page==='MediMind'?casePage():page==='Course Activity'?courseActivityPage(courseActivityById.get(courseActivityId),state.courseWork[courseActivityId],state.mode):page==='Course Materials'?courseMaterialsPage():glossary();$('#app').innerHTML=shell(content);$('h1')?.setAttribute('tabindex','-1');document.documentElement.lang='en';syncMenu();}
function currentQuestion(){return page==='Exam Mode'?questionById.get(String(state.exam.ids[state.exam.index])):question}
function submit(){const inExam=page==='Exam Mode',q=currentQuestion(),value=questionDraft(q,inExam);if(value===''||(Array.isArray(value)&&(value.some(x=>x==='')||(q.type==='build'&&value.length!==q.options.length)))){$('#answer-error').textContent=Array.isArray(value)?'Complete every item before submitting.':'Enter or choose an answer first.';return}
 if(inExam){const exam=state.exam;exam.results[exam.index]={value:structuredClone(value)};if(exam.index===exam.ids.length-1){if(exam.results.length!==exam.ids.length||exam.results.some(x=>!x)){ $('#answer-error').textContent='Answer all questions before submitting.';return}exam.finished=true;exam.results=exam.results.map((r,i)=>({...r,correct:grade(questionById.get(String(exam.ids[i])),r.value)}));if(!exam.recorded){exam.results.forEach((r,i)=>recordAnswer(state,questionById.get(String(exam.ids[i])),r.value,r.correct));exam.recorded=true;state.examHistory.push({date:Date.now(),correct:exam.results.filter(r=>r.correct).length,total:exam.ids.length})}}else exam.index++;save();render();window.scrollTo(0,0)}
 else{const correct=recordAnswer(state,q,value);feedback={correct,value:structuredClone(value)};if(quick)quick.results[quick.index]=feedback;save();render();$('.feedback')?.focus({preventScroll:true})}}
function exportProgress(){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='intro-computing-progress.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function updateCourseField(el){state.courseWork[courseActivityId]||={values:{}};const entry=state.courseWork[courseActivityId];entry.values[el.dataset.courseField]=el.value;entry.submitted=false;if(entry.review==='understood')entry.review=null;save();document.querySelector('.course-answer')?.remove()}
document.addEventListener('input',e=>{const el=e.target;if(el.dataset.courseField){updateCourseField(el);return}if(el.dataset.roleNote!==undefined){state.caseRoleNotes[caseIndex]||=['',''];state.caseRoleNotes[caseIndex][Number(el.dataset.roleNote)]=el.value;caseRevealed=false;document.querySelector('.tutor-guidance')?.remove();document.querySelector('.case-study .feedback')?.remove();save();return}if(el.id==='glossary-search'){const position=el.selectionStart;search=el.value;render();$('#glossary-search').focus();$('#glossary-search').setSelectionRange(position,position)}else if(el.matches('[data-note]')){state.caseNotes[caseIndex]||=['','','',''];state.caseNotes[caseIndex][Number(el.dataset.note)]=el.value;caseRevealed=false;document.querySelector('.tutor-guidance')?.remove();document.querySelector('.case-study .feedback')?.remove();save()}else if(el.dataset.response==='fill')setDraft(currentQuestion(),el.value,page==='Exam Mode')});
document.addEventListener('change',e=>{const el=e.target;if(el.dataset.courseField){updateCourseField(el);return}if(el.id==='module-filter'){moduleFilter=Number(el.value);question=null;feedback=null;flashId=null;flipped=false;render()}else if(el.id==='format-filter'){format=el.value;question=null;feedback=null;render()}else if(el.id==='activity-select'){question=questionById.get(el.value);feedback=null;render()}else if(el.dataset.response==='choice')setDraft(currentQuestion(),el.value,page==='Exam Mode');else if(el.dataset.response==='array'){const q=currentQuestion(),draft=[...questionDraft(q,page==='Exam Mode')];draft[Number(el.dataset.index)]=el.value;setDraft(q,draft,page==='Exam Mode')}});
document.addEventListener('click',e=>{const el=e.target.closest('button,a');if(!el)return;
 if(el.classList.contains('skip-link')){e.preventDefault();$('main').focus();return}
 if(el.dataset.sourceId){e.preventDefault();navigate('Course Materials');document.getElementById('source-'+el.dataset.sourceId)?.scrollIntoView();return}
 if(el.dataset.courseActivity){navigate('Course Activity',{activity:el.dataset.courseActivity});return}
 if(el.dataset.courseReview){const entry=state.courseWork[courseActivityId];const activity=courseActivityById.get(courseActivityId);if(entry?.submitted&&checkCourseActivity(activity,entry.values).complete){entry.review=el.dataset.courseReview;save();render()}return}
 if(el.dataset.nav){e.preventDefault();navigate(el.dataset.nav);return}
 if(el.dataset.module){navigate('Module',{module:Number(el.dataset.module)});return}
 if(el.dataset.lesson){state.last=el.dataset.lesson;save();navigate('Learn',{lesson:el.dataset.lesson});return}
 if(el.dataset.retry){const q=questionById.get(el.dataset.retry);delete state.drafts[q.id];save();navigate('Practice',{module:q.module,question:q.id});return}
 if(el.dataset.understood){const m=state.mistakes[el.dataset.understood];m.archived=!m.archived;save();render();return}
 if(el.dataset.rate){const old=el.dataset.card;rateCard(state,old,Number(el.dataset.rate));save();const pool=browseAll?allLessons.filter(l=>!moduleFilter||l.module===moduleFilter):dueCards(state,moduleFilter);flashId=pool.find(l=>l.id!==old)?.id||pool[0]?.id;flipped=false;render();return}
 if(el.dataset.addStep!==undefined||el.dataset.removeStep!==undefined){const q=currentQuestion(),draft=[...questionDraft(q,page==='Exam Mode')];if(el.dataset.addStep!==undefined)draft.push(q.options[Number(el.dataset.addStep)]);else draft.splice(Number(el.dataset.removeStep),1);setDraft(q,draft,page==='Exam Mode');render();return}
 if(el.dataset.move!==undefined){const q=currentQuestion(),value=[...questionDraft(q,page==='Exam Mode')],i=Number(el.dataset.move),j=i+Number(el.dataset.direction);[value[i],value[j]]=[value[j],value[i]];setDraft(q,value,page==='Exam Mode');render();document.querySelector(`[data-move="${j}"][data-direction="${el.dataset.direction}"]`)?.focus();return}
 if(el.dataset.concept){const q=questionById.get(el.dataset.question),value=el.dataset.value,correct=recordAnswer(state,q,value);state.checks[el.dataset.concept]={correct,value};save();render();return}
 if(el.dataset.case!==undefined){caseIndex=Number(el.dataset.case);caseRevealed=false;history.replaceState(null,'',`#MediMind?stage=${caseIndex}`);render();return}
 if(el.classList.contains('mobile-toggle')){const open=$('#app').classList.toggle('mobile-open');el.setAttribute('aria-expanded',String(open));syncMenu();return}
 switch(el.id){
 case 'language':state.mode=state.mode==='bilingual'?'english':'bilingual';save();render();break;
 case 'module-practice':navigate('Practice',{module:moduleFilter});break;
 case 'module-flashcards':navigate('Flashcards',{module:moduleFilter});break;
 case 'complete-lesson':if(!state.done.includes(lesson))state.done.push(lesson);{const idx=allLessons.findIndex(l=>l.id===lesson);state.last=allLessons[(idx+1)%allLessons.length].id;save();navigate('Learn',{lesson:state.last})}break;
 case 'flip-card':flipped=!flipped;render();break;
 case 'toggle-browse':browseAll=!browseAll;flashId=null;flipped=false;render();break;
 case 'quick-quiz':{const shuffled=[...questions].filter(q=>q.type!=='identify').sort(()=>Math.random()-.5);quick={ids:shuffled.slice(0,5).map(q=>q.id),index:0,results:[]};quick.ids.forEach(id=>delete state.drafts[id]);navigate('Practice');question=questionById.get(String(quick.ids[0]));render();break}
 case 'submit-answer':submit();break;
 case 'next-question':feedback=null;if(quick){if(quick.index===quick.ids.length-1)quick.finished=true;else{quick.index++;question=questionById.get(String(quick.ids[quick.index]))}}else{question=pickQuestion(question.id);if(question)delete state.drafts[question.id]}save();render();window.scrollTo(0,0);break;
 case 'start-exam':state.exam=createExam();save();render();break;
 case 'exam-back':state.exam.index--;save();render();break;
 case 'new-exam':state.exam=null;save();render();break;
 case 'check-course-work':{const activity=courseActivityById.get(courseActivityId);state.courseWork[courseActivityId]||={values:{}};const entry=state.courseWork[courseActivityId],result=checkCourseActivity(activity,entry.values);entry.submitted=true;if(result.complete){entry.attemptedAt=Date.now();if((result.objectiveTotal&&result.objectiveScore<result.objectiveTotal)||result.numericChecks?.some(x=>!x.correct))entry.review='needs-review'}save();render();$('#course-validation')?.scrollIntoView({block:'center'});break}
 case 'reveal-case':{const notes=state.caseNotes[caseIndex]||[],roleNotes=state.caseRoleNotes[caseIndex]||[];if(notes.length!==4||notes.some(x=>!x.trim())||roleNotes.length!==2||roleNotes.some(x=>!x.trim())){$('#case-error').textContent='Answer both original role questions and the four reflection prompts before revealing tutor guidance.';break}caseRevealed=true;if(!state.lecturerCaseDone.includes(caseIndex))state.lecturerCaseDone.push(caseIndex);if(!state.caseDone.includes(caseIndex))state.caseDone.push(caseIndex);save();render();break}
 case 'next-case':if(caseIndex===cases.length-1)navigate('Learn');else{caseIndex++;caseRevealed=false;history.replaceState(null,'',`#MediMind?stage=${caseIndex}`);render();window.scrollTo(0,0)}break;
 case 'export-progress':case 'export-progress-footer':exportProgress();break;
 }
});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('#app').classList.remove('mobile-open');$('.mobile-toggle')?.setAttribute('aria-expanded','false');syncMenu()}});
function syncMenu(){const hidden=innerWidth<=700&&!$('#app').classList.contains('mobile-open');$('.sidebar').inert=hidden;$('.mobile-toggle').setAttribute('aria-expanded',String(!hidden&&innerWidth<=700))}
window.addEventListener('resize',syncMenu);
readRoute();
